class Counter {
    static int sharedCounter = 0; // one copy, shared by the whole class

    static void increment() {
        sharedCounter++;
    }

    static int getSharedCounter() { // callable as Counter.getSharedCounter()
        return sharedCounter;
    }
}

public class Main {
    public static void main(String[] args) {
        Counter.increment();
        Counter.increment();
        System.out.println(Counter.getSharedCounter());
    }
}

