#include <iostream>
using namespace std;

class Counter {
public:
    static int sharedCounter; // one copy, shared by the whole class

    static void increment() {
        sharedCounter++;
    }

    static int getSharedCounter() { // callable as Counter::getSharedCounter()
        return sharedCounter;
    }
};

int Counter::sharedCounter = 0;

int main() {
    Counter::increment();
    Counter::increment();
    cout << Counter::getSharedCounter() << endl;
    return 0;
}

