class Employee {
    private static int totalEmployees = 0; // ONE copy, shared by every Employee object
    private String name; // each object gets its OWN copy of this

    Employee(String name) {
        this.name = name;
        totalEmployees++; // every new Employee bumps the SAME shared counter
    }

    public String getName() {
        return name;
    }

    // static method: belongs to the class itself, not to any one object
    public static int getTotalEmployees() {
        return totalEmployees;
    }
}

public class Main {
    public static void main(String[] args) {
        System.out.println("Before hiring: " + Employee.getTotalEmployees());

        Employee e1 = new Employee("Asha");
        Employee e2 = new Employee("Raj");
        Employee e3 = new Employee("Meera");

        System.out.println("After hiring: " + Employee.getTotalEmployees());
        System.out.println(e1.getName() + ", " + e2.getName() + ", " + e3.getName());
    }
}

