#include <iostream>
#include <string>
using namespace std;

class Employee {
private:
    static int totalEmployees; // declared here, ONE copy shared by every Employee object
    string name; // each object gets its OWN copy of this

public:
    Employee(string name) : name(name) {
        totalEmployees++; // every new Employee bumps the SAME shared counter
    }

    string getName() {
        return name;
    }

    // static method: belongs to the class itself, not to any one object
    static int getTotalEmployees() {
        return totalEmployees;
    }
};

int Employee::totalEmployees = 0; // static members must be defined once outside the class

int main() {
    cout << "Before hiring: " << Employee::getTotalEmployees() << endl;

    Employee e1("Asha");
    Employee e2("Raj");
    Employee e3("Meera");

    cout << "After hiring: " << Employee::getTotalEmployees() << endl;
    cout << e1.getName() << ", " << e2.getName() << ", " << e3.getName() << endl;

    return 0;
}
